const HOSTEL_OPTIONS=[{value:'none',label:'No Hostel',annual:0,deposit:0},{value:'triple_non_ac',label:'Triple Sharing (Non-AC)',annual:85000,deposit:5000},{value:'triple_ac',label:'Triple Sharing (AC)',annual:120000,deposit:5000},{value:'double_non_ac',label:'Double Sharing (Non-AC)',annual:95000,deposit:5000},{value:'double_ac',label:'Double Sharing (AC)',annual:130000,deposit:5000}];
const TRANSPORT_OPTIONS=[{value:'none',label:'No Transport',annual:0},{value:'dehradun',label:'Dehradun Route',annual:17000},{value:'vikasnagar',label:'Vikasnagar Route',annual:17000},{value:'paonta_sahib',label:'Paonta Sahib Route',annual:20000}];
const REC_SEM=4000, EXAM_GEN=3500, EXAM_PHAR=7000, ONE_TIME=16000;
const rows=[];schools.forEach((s,si)=>s.courses.forEach((c,ci)=>rows.push({school:s.label,schoolName:s.name,si,ci,...c})));
function cleanName(html){const div=document.createElement('div');div.innerHTML=String(html||'');return div.textContent.replace(/\s+/g,' ').trim()}
function parseFee(value){const n=parseInt(String(value||'').replace(/[^0-9]/g,''),10);return Number.isFinite(n)?n:0}
function inr(value){return '₹'+Math.round(value||0).toLocaleString('en-IN')}
function isPharma(name){return /pharm|pharma|d\.?pharm|b\.?pharm|m\.?pharm/i.test(name)}
function durationOptions(str){const matches=[...String(str||'').matchAll(/(\d+(?:\.\d+)?)\s*Years?/gi)].map(m=>Number(m[1])).filter(Boolean);return [...new Set(matches)].sort((a,b)=>b-a)}
function validityDate(){const d=new Date();d.setDate(d.getDate()+10);return d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
function optionLabel(opt){if(!opt.annual)return opt.label;return opt.label+' ('+inr(opt.annual)+'/yr'+(opt.deposit?' + '+inr(opt.deposit)+' deposit':'')+')'}
function populate(){const program=document.getElementById('programSelect');program.innerHTML='<option value="" selected disabled>Choose your program</option>'+schools.map((s,si)=>'<optgroup label="'+s.label.replace(/"/g,'&quot;')+'">'+s.courses.map((c,ci)=>'<option value="'+rows.findIndex(r=>r.si===si&&r.ci===ci)+'">'+cleanName(c.name)+' - '+c.duration+'</option>').join('')+'</optgroup>').join('');document.getElementById('hostelSelect').innerHTML=HOSTEL_OPTIONS.map(o=>'<option value="'+o.value+'">'+optionLabel(o)+'</option>').join('');document.getElementById('transportSelect').innerHTML=TRANSPORT_OPTIONS.map(o=>'<option value="'+o.value+'">'+optionLabel(o)+'</option>').join('')}
function updateDuration(row){const wrap=document.getElementById('durationField');const sel=document.getElementById('durationSelect');const opts=durationOptions(row.duration);if(opts.length>1){wrap.style.display='block';const prev=Number(sel.value)||opts[0];sel.innerHTML=opts.map(y=>'<option value="'+y+'">'+y+' Years</option>').join('');sel.value=opts.includes(prev)?prev:opts[0]}else{wrap.style.display='none';sel.innerHTML=opts[0]?'<option value="'+opts[0]+'">'+opts[0]+' Years</option>':'<option value="1">1 Year</option>'}}
function calcAddOns(sems){const h=HOSTEL_OPTIONS.find(o=>o.value===document.getElementById('hostelSelect').value)||HOSTEL_OPTIONS[0];const t=TRANSPORT_OPTIONS.find(o=>o.value===document.getElementById('transportSelect').value)||TRANSPORT_OPTIONS[0];return {hostel:h,transport:t,charges:Array.from({length:sems},(_,i)=>({hostel:h.annual?Math.round(h.annual/2)+(i===0?(h.deposit||0):0):0,transport:t.annual?Math.round(t.annual/2):0}))}}
function semRows(row,annual,years,pct){const sems=Math.max(1,Math.round(years*2));const tuition=Math.round(annual/2);const exam=isPharma(cleanName(row.name))?EXAM_PHAR:EXAM_GEN;const add=calcAddOns(sems);let total=0,savedTotal=0;const body=[];for(let i=0;i<sems;i++){const scholarship=Math.round(tuition*pct/100);const one=i===0?ONE_TIME:0;const payable=tuition-scholarship+REC_SEM+exam+one+add.charges[i].hostel+add.charges[i].transport;total+=payable;savedTotal+=scholarship;body.push({sem:i+1,tuition,scholarship,rec:REC_SEM,exam,one,hostel:add.charges[i].hostel,transport:add.charges[i].transport,payable})}return {body,total,savedTotal,add}}
function render(){const selectedProgram=document.getElementById('programSelect').value;if(selectedProgram===''){document.getElementById('tableTitle').textContent='Semester Fee Breakdown';document.getElementById('validityNote').textContent='';document.getElementById('breakdownArea').innerHTML='<div class="empty">Choose your program to view the fee breakdown.</div>';document.getElementById('summaryCards').innerHTML='';document.getElementById('notesArea').innerHTML='';return}const row=rows[Number(selectedProgram)];if(!row)return;updateDuration(row);const category=document.getElementById('categorySelect').value;const annual=parseFee(category==='ai'?row.feeAI:row.feeUK);const pct=Number(document.getElementById('scholarshipSelect').value)||0;const years=Number(document.getElementById('durationSelect').value)||durationOptions(row.duration)[0]||1;const area=document.getElementById('breakdownArea');document.getElementById('tableTitle').textContent=cleanName(row.name);document.getElementById('validityNote').textContent='▣ Valid till '+validityDate()+' (default 10 days)';if(!annual){area.innerHTML='<div class="empty">Fee for this programme is on request.</div>';document.getElementById('summaryCards').innerHTML='';document.getElementById('notesArea').innerHTML='';return}const result=semRows(row,annual,years,pct);area.innerHTML='<table class="fee-table"><thead><tr><th>Sem</th><th>Tuition</th><th>Scholarship*</th><th>Recurring</th><th>Exam</th><th>One Time</th><th>Hostel</th><th>Transport</th><th>Payable</th></tr></thead><tbody>'+result.body.map(r=>'<tr><td>Sem '+r.sem+'</td><td>'+inr(r.tuition)+'</td><td>'+(r.scholarship?'-'+inr(r.scholarship):'—')+'</td><td>'+inr(r.rec)+'</td><td>'+inr(r.exam)+'</td><td>'+(r.one?inr(r.one):'—')+'</td><td>'+(r.hostel?inr(r.hostel):'—')+'</td><td>'+(r.transport?inr(r.transport):'—')+'</td><td><strong>'+inr(r.payable)+'</strong></td></tr>').join('')+'<tr class="total-row"><td colspan="8">Grand Total</td><td>'+inr(result.total)+'</td></tr></tbody></table>';document.getElementById('summaryCards').innerHTML=[['Annual Fee',inr(annual),'₹'],['Duration',years+' Years','⌛'],['Scholarship* Saving',inr(result.savedTotal),'♕'],['Net Payable',inr(result.total),'₹']].map(m=>'<div class="metric" data-icon="'+m[2]+'"><span>'+m[0]+'</span><strong>'+m[1]+'</strong></div>').join('');const notes=[];if(pct>0)notes.push('<strong>Scholarship*:</strong> '+pct+'% is applied on tuition fee only, subject to terms and conditions. Recurring, exam, hostel, transport and one-time charges are not discounted.');notes.push('<strong>One-time charges:</strong> Semester 1 includes admission processing and uniform charges of '+inr(ONE_TIME)+'.');notes.push('<strong>Hostel rule:</strong> Hostel is booked for one full academic year (2 semesters).');notes.push('<strong>Due dates:</strong> Odd semester fee by 31 July and even semester fee by 31 December.');document.getElementById('notesArea').innerHTML=notes.map(n=>'<div class="note">'+n+'</div>').join('')}
populate();['programSelect','categorySelect','scholarshipSelect','durationSelect','hostelSelect','transportSelect'].forEach(id=>document.getElementById(id).addEventListener('change',render));render();
</script>
